# Generated by DataReady
# 示例：与经过用户确认的 Cleaning Plan 对应。

import pandas as pd

df = pd.read_excel("retail_operations_dirty.xlsx")

# 1. 删除完全重复记录
df = df.drop_duplicates()

# 2. 统一空值编码
df["delivery_cost"] = df["delivery_cost"].replace(["N/A", "-", "NA"], pd.NA)

# 3. 标准化日期格式
df["date"] = pd.to_datetime(df["date"], errors="coerce").dt.strftime("%Y-%m-%d")

# 4. 统一城市名称（需要用户确认）
df["city"] = df["city"].replace({
    "上海市": "上海",
    "Shanghai": "上海",
    "上海 ": "上海",
})

df.to_excel("retail_operations_cleaned.xlsx", index=False)
